/**
 * @fileoverview Validator for AI model plan outputs.
 * Ensures the structured plan generated by an LLM adheres to strict safety,
 * allowlists, and database tool schemas before execution or user review.
 * @module agents/model-validator
 */

import { ALLOWED_OPERATIONS } from '../db/schema-validator.js';
import { PLANNER_TABLES } from '../db/policy.js';

/**
 * Validates the raw JSON output parsed from an LLM plan response.
 * Ensures that it is a safe array of allowed operations, targeting allowed tables,
 * with structured data payloads rather than arbitrary SQL.
 * 
 * @param {any} plan - The parsed output from the model.
 * @returns {{ valid: boolean, operations: Array<Object>, errors: string[] }}
 */
export function validateModelPlan(plan) {
  const errors = [];

  let operations = plan;
  if (plan && typeof plan === 'object' && !Array.isArray(plan) && Array.isArray(plan.operations)) {
    operations = plan.operations;
  }

  if (!Array.isArray(operations)) {
    return {
      valid: false,
      operations: [],
      errors: ['Model plan must be a JSON array of operations or an object with an operations array.']
    };
  }

  if (operations.length === 0) {
    return {
      valid: false,
      operations: [],
      errors: ['Model plan contains 0 operations.']
    };
  }

  const sanitizedOperations = [];

  for (let i = 0; i < operations.length; i++) {
    const op = operations[i];
    if (!op || typeof op !== 'object') {
      errors.push(`Operation at index ${i} is not a valid object.`);
      continue;
    }

    const rawOp = typeof op.operation === 'string' ? op.operation.toUpperCase().trim() : '';
    const rawTable = typeof (op.table || op.tableName) === 'string' ? (op.table || op.tableName).toLowerCase().trim() : '';
    const data = op.data;

    // Check operation
    if (!ALLOWED_OPERATIONS.has(rawOp)) {
      errors.push(`Operation at index ${i} has unsupported operation '${op.operation}'. Allowed: ${Array.from(ALLOWED_OPERATIONS).join(', ')}.`);
    }

    // Check table
    if (!PLANNER_TABLES.has(rawTable)) {
      errors.push(`Operation at index ${i} targets unsupported table '${op.table || op.tableName}'. Allowed: ${Array.from(PLANNER_TABLES).join(', ')}.`);
    }

    // Check data
    if (!data || typeof data !== 'object' || Array.isArray(data)) {
      errors.push(`Operation at index ${i} data must be a key-value object.`);
    }

    if (errors.length === 0) {
      sanitizedOperations.push({
        operation: rawOp,
        table: rawTable,
        data
      });
    }
  }

  return {
    valid: errors.length === 0,
    operations: errors.length === 0 ? sanitizedOperations : [],
    errors
  };
}
